// UI 踰덉뿭 ?ы띁: tx(key, langCode)
// ?ъ슜踰? tx("?꾨즺!", lang?.code) ???좏깮 ?몄뼱濡??먮룞 諛섑솚

// tx(obj, langCode): ?몄뼱肄붾뱶??留욌뒗 踰덉뿭 諛섑솚
// obj 媛 臾몄옄?댁씠硫?UI_TRANSLATIONS ?뚯씠釉?李몄“
// obj 媛 媛앹껜?대㈃ 吏곸젒 ?대떦 ?몄뼱媛?諛섑솚
function tx(obj, langCode) {
  if (!obj) return "";
  const lc = langCode ?? "ko";
  // 臾몄옄???? UI_TRANSLATIONS ?뚯씠釉?李몄“
  if (typeof obj === "string") {
    const row = UI_TRANSLATIONS[obj];
    if (row) return row[lc] ?? row.en ?? row.ko ?? obj;
    return obj;
  }
  // 媛앹껜: 吏곸젒 ?몄뼱媛?諛섑솚
  if (obj[lc] !== undefined) return obj[lc];
  if (obj.en !== undefined) return obj.en;
  return obj.ko ?? "";
}

// getLang(lang): lang 媛앹껜?먯꽌 肄붾뱶 異붿텧
function getLang(lang) {
  return lang?.code ?? "ko";
}

// txUI(ko, lang): UI ?띿뒪???⑥텞 ?ы띁
// ?ъ슜: txUI("?꾨즺!", lang) ???좏깮 ?몄뼱 ?먮룞 諛섑솚
function txUI(ko, lang) {
  return tx(ko, lang?.code);
}

