async function callClaude(messages, system) {
  if (!rateLimiter.check()) return "?좉퉸! ?덈Т 鍮좊Ⅴ寃?蹂대궡怨??덉뼱?? ?좎떆 ???ㅼ떆 ?쒕룄?댁쨾! ?삃";
  try {
    const r = await fetch("/api/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: "claude-sonnet-4-6",
        max_tokens: 1000,
        system,
        messages: trimHistory(messages),
      }),
    });
    if (!r.ok) return API_ERRORS[r.status] || `?ㅻ쪟媛 諛쒖깮?덉뼱?? (${r.status})`;
    const d = await r.json();
    if (d.error) return `?ㅻ쪟: ${d.error.message}`;
    return d.content?.map(b => b.text || "").join("") || "?묐떟??諛쏆? 紐삵뻽?댁슂.";
  } catch(e) {
    if (!navigator.onLine) return "?명꽣???곌껐???뺤씤?댁쨾! ?뱻";
    return "?곌껐 ?ㅻ쪟媛 諛쒖깮?덉뼱?? ?ㅼ떆 ?쒕룄?댁쨾! ?쁾";
  }
}

