  // ??V148: 湲곗〈 媛?낆옄 留덉씠洹몃젅?댁뀡 泥댄겕 (dataOwnershipAgreed ?놁쑝硫??앹뾽)
  useEffect(()=>{
    if(!user) return;
    getDoc(doc(db, "users", user.uid)).then(d => {
      if(d.exists() && d.data().dataOwnershipAgreed === undefined) {
        setShowMigration(true);
      }
    }).catch(()=>{});
  },[user]);

  // ??V349: SW 罹먯떆 踰꾩뒪??+ 罹먯떆 踰꾩뒪???앹뾽
  useEffect(()=>{
    const VER_KEY = "hc_app_ver";
    const stored = localStorage.getItem(VER_KEY);
    if (stored && stored !== APP_VERSION) {
      // 踰꾩쟾???ㅻⅤ硫??앹뾽 ?쒖떆
      setShowCacheBust(true);
    }
    localStorage.setItem(VER_KEY, APP_VERSION);

    // SW ?깅줉 + 踰꾩쟾 ?꾨떖 + SW_UPDATED ?섏떊 ???먮룞 ?덈줈怨좎묠
    if ("serviceWorker" in navigator) {
      // SW_UPDATED 硫붿떆吏 ?섏떊 ???먮룞 ?덈줈怨좎묠
      navigator.serviceWorker.addEventListener("message", (e) => {
        if (e.data?.type === "SW_UPDATED") {
          window.location.reload(true);
        }
      });

      navigator.serviceWorker.register("/sw.js").then(reg => {
        const sw = reg.active || reg.installing || reg.waiting;
        if (sw) sw.postMessage({ type: "SET_VERSION", version: APP_VERSION });
        navigator.serviceWorker.ready.then(r => {
          r.active?.postMessage({ type: "SET_VERSION", version: APP_VERSION });
        });

        // SW ?녿뒗 泥?諛⑸Ц 湲곌린 ??而⑦듃濡ㅻ윭 ?놁쑝硫?利됱떆 ?덈줈怨좎묠
        if (!navigator.serviceWorker.controller) {
          navigator.serviceWorker.ready.then(() => {
            if (navigator.serviceWorker.controller) {
              window.location.reload(true);
            }
          });
        }
      }).catch(()=>{});
    }
  }, []);

